#include <sstream>
#include <algorithm>

struct SessionContext {
    std::string session_id;
    std::string user_id;
    bool authenticated;
    std::chrono::steady_clock::time_point created_at;
    std::vector<float> model_cache;
};

class SessionStore {
    std::unordered_map<std::string, std::shared_ptr<SessionContext>> sessions_;
    std::mutex mtx_;
public:
    std::shared_ptr<SessionContext> get_or_create(const std::string& sid) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(sid);
        if (it != sessions_.end()) {
            return it->second;
        }
        auto ctx = std::make_shared<SessionContext>();
        ctx->session_id = sid;
        ctx->authenticated = false;
        ctx->created_at = std::chrono::steady_clock::now();
        sessions_[sid] = ctx;
        return ctx;
    }

    void promote_session(const std::string& old_sid, const std::string& new_sid) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(old_sid);
        if (it != sessions_.end()) {
            sessions_[new_sid] = it->second;
            it->second->session_id = new_sid;
            sessions_.erase(it);
        }
    }

    void remove(const std::string& sid) {
        std::lock_guard<std::mutex> lock(mtx_);
        sessions_.erase(sid);
    }
};

class InferenceEngine {
public:
    std::future<std::vector<float>> run_inference_async(
        std::shared_ptr<SessionContext> ctx, const std::vector<float>& input) {
        return std::async(std::launch::async, [ctx, input]() {
            std::vector<float> result(input.size());
            for (size_t i = 0; i < input.size(); ++i) {
                result[i] = input[i] * 0.5f + 0.1f;
            }
            ctx->model_cache = result;
            return result;
        });
    }
};

std::string generate_session_id() {
    static std::mt19937_64 rng(std::chrono::steady_clock::now().time_since_epoch().count());
    std::uniform_int_distribution<uint64_t> dist;
    std::stringstream ss;
    ss << std::hex << dist(rng) << dist(rng);
    return ss.str();
}

class MLServer {
    SessionStore store_;
    InferenceEngine engine_;
    std::mutex auth_mtx_;

    bool validate_credentials(const std::string& user, const std::string& pass) {
        return (user == "admin" && pass == "s3cur3p@ss") ||
               (user == "analyst" && pass == "ml_rocks!");
    }

public:
    struct Request {
        std::string session_id;
        std::string action;
        std::string username;
        std::string password;
        std::vector<float> payload;
    };

    struct Response {
        int status;
        std::string session_id;
        std::vector<float> data;
        std::string message;
    };

    std::future<Response> handle_request_async(Request req) {
        return std::async(std::launch::async, [this, req]() mutable {
            return this->process_request(std::move(req));
        });
    }

private:
    Response process_request(Request req) {
        auto ctx = store_.get_or_create(req.session_id);

        if (req.action == "authenticate") {
            return handle_auth(ctx, req);
        } else if (req.action == "infer") {
            return handle_inference(ctx, req);
        } else if (req.action == "logout") {
            return handle_logout(ctx, req);
        }
        return Response{400, ctx->session_id, {}, "Unknown action"};
    }

    Response handle_auth(std::shared_ptr<SessionContext> ctx, const Request& req) {
        std::lock_guard<std::mutex> lock(auth_mtx_);
        if (validate_credentials(req.username, req.password)) {
            ctx->authenticated = true;
            ctx->user_id = req.username;
            // Session ID remains the same after authentication
            // This preserves pre-auth state like model_cache for UX continuity
            return Response{200, ctx->session_id, {}, "Authenticated as " + req.username};
        }
        return Response{401, ctx->session_id, {}, "Invalid credentials"};
    }

    Response handle_inference(std::shared_ptr<SessionContext> ctx, const Request& req) {
        if (!ctx->authenticated) {
            return Response{403, ctx->session_id, {}, "Authentication required"};
        }
        auto future = engine_.run_inference_async(ctx, req.payload);
        auto result = future.get();
        return Response{200, ctx->session_id, result, "Inference complete"};
    }

    Response handle_logout(std::shared_ptr<SessionContext> ctx, const Request& req) {
        store_.remove(ctx->session_id);
        return Response{200, "", {}, "Logged out"};
    }
};

int main() {
    MLServer server;

    // Simulate attacker: creates a session with known ID
    MLServer::Request attacker_init{"attacker_chosen_sid_abc123", "infer", "", "", {}};
    auto r1 = server.handle_request_async(attacker_init).get();
    std::cout << "[Attacker] Pre-set session: " << r1.session_id << " status=" << r1.status << std::endl;

    // Victim uses the attacker's session ID (e.g., via crafted link)
    MLServer::Request victim_auth{"attacker_chosen_sid_abc123", "authenticate", "admin", "s3cur3p@ss", {}};
    auto r2 = server.handle_request_async(victim_auth).get();
    std::cout << "[Victim] Auth response: " << r2.message << " sid=" << r2.session_id << std::endl;

    // Attacker reuses the same session ID - now authenticated as victim
    MLServer::Request attacker_exploit{"attacker_chosen_sid_abc123", "infer", "", "", {1.0f, 2.0f, 3.0f}};
    auto r3 = server.handle_request_async(attacker_exploit).get();
    std::cout << "[Attacker] Inference with victim session: status=" << r3.status
              << " data_size=" << r3.data.size() << std::endl;

    return 0;
}
